// Map countries to preferred language
const countryToLang = {
    'MA': 'ar', 'DZ': 'ar', 'TN': 'ar', 'LY': 'ar', 'EG': 'ar',
    'FR': 'fr', 'ES': 'es', 'MX': 'es', 'AR': 'es', 'CO': 'es',
    'IT': 'it', 'DE': 'de', 'CN': 'zh', 'JP': 'ja', 'KR': 'ko',
    'BR': 'pt', 'PT': 'pt', 'RU': 'ru', 'TR': 'tr', 'IN': 'hi',
    'PK': 'ur', 'ID': 'id', 'PH': 'tl', 'VN': 'vi', 'TH': 'th',
    'RO': 'ro', 'GR': 'el', 'HU': 'hu', 'CZ': 'cs', 'SE': 'sv',
    'DK': 'da', 'FI': 'fi', 'NO': 'no'
};

async function detectLanguageByIP() {
    // 1. Try Browser Language First
    const browserLangs = navigator.languages || [navigator.language];
    for (const bLang of browserLangs) {
        const shortLang = bLang.split('-')[0].toLowerCase();
        if (translations[shortLang]) {
            console.log('Detected browser language:', shortLang);
            return shortLang;
        }
    }

    // 2. Fallback to IP Geolocation
    try {
        console.log('Trying IP detection...');
        const response = await fetch('https://ipapi.co/json/');
        if (!response.ok) throw new Error('IP API response not OK');

        const data = await response.json();
        const countryCode = data.country_code;
        console.log('IP Country detected:', countryCode);

        console.log('IP Country detected:', countryCode);

        // Map IL (Israel) to en (English) instead of he (Hebrew) to remove Hebrew support
        if (countryCode === 'IL') return 'en';

        const detected = countryToLang[countryCode] || 'en';
        return translations[detected] ? detected : 'en';
    } catch (error) {
        console.error('IP detection failed:', error);
        return 'en';
    }
}

function setLang(lang, isUser = false) {
    if (!translations[lang]) lang = 'en';

    // Save language preference
    localStorage.setItem('fg_lang', lang);
    if (isUser) {
        localStorage.setItem('fg_manual', 'true');
    }

    const rtlLangs = ['ar', 'fa', 'ur', 'dv', 'ps', 'sd', 'ug', 'yi', 'pnb'];
    // Hebrew (he) removed from RTL list
    const isRTL = rtlLangs.includes(lang);

    document.documentElement.dir = isRTL ? 'rtl' : 'ltr';
    document.documentElement.lang = lang;
    document.body.style.direction = isRTL ? 'rtl' : 'ltr';

    const navbar = document.querySelector('.navbar');
    if (navbar) navbar.style.flexDirection = isRTL ? 'row-reverse' : 'row';

    const elements = document.querySelectorAll('[data-i18n]');
    elements.forEach(el => {
        const key = el.getAttribute('data-i18n');
        const translation = (translations[lang] && translations[lang][key])
            ? translations[lang][key]
            : (translations['en'][key] || key);

        if (key === 'login_welcome') {
            console.log(`[DEBUG] setLang: lang=${lang}, key=${key}, translation=${translation}, hasZh=${!!translations['zh']}, zhVal=${translations['zh'] ? translations['zh'][key] : 'N/A'}`);
        }

        if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') {
            el.placeholder = translation;
        } else {
            el.innerHTML = translation;
        }
    });

    updateLanguageUI(lang);
    window.dispatchEvent(new CustomEvent('langChanged', { detail: { lang } }));
}

function updateLanguageUI(lang) {
    document.querySelectorAll('.lang-option').forEach(opt => {
        opt.classList.remove('active');
        const onclickAttr = opt.getAttribute('onclick');
        if (onclickAttr && onclickAttr.includes(`'${lang}'`)) {
            opt.classList.add('active');
            const display = document.getElementById('currentLangDisplay');
            if (display) {
                const currentText = opt.innerText;
                const emoji = currentText.split(' ')[0];
                display.innerText = " " + emoji + " " + (lang.toUpperCase());
            }
        }
    });
}

function getLang() {
    return localStorage.getItem('fg_lang') || 'en';
}

function toggleLangDropdown(e) {
    if (e) e.stopPropagation();
    const selector = document.querySelector('.lang-selector');
    if (selector) selector.classList.toggle('open');
}

document.addEventListener('click', (e) => {
    const selector = document.querySelector('.lang-selector');
    if (selector && !selector.contains(e.target)) {
        selector.classList.remove('open');
    }
});

/**
 * Extract language code from URL
 * Supports formats: /fr/, /ar/, ?lang=fr
 */
function getLanguageFromURL() {
    // Check if language was injected by PHP (from URL parameter)
    if (window.urlLang && translations[window.urlLang]) {
        console.log('Language from PHP injection:', window.urlLang);
        return window.urlLang;
    }

    // Check URL path for language code (e.g., /fr/, /ar/)
    const pathMatch = window.location.pathname.match(/^\/([a-z]{2,3})\/?/);
    if (pathMatch && translations[pathMatch[1]]) {
        console.log('Language from URL path:', pathMatch[1]);
        return pathMatch[1];
    }

    // Check URL query parameter (e.g., ?lang=fr)
    const urlParams = new URLSearchParams(window.location.search);
    const langParam = urlParams.get('lang');
    if (langParam && translations[langParam]) {
        console.log('Language from URL parameter:', langParam);
        return langParam;
    }

    return null;
}

/**
 * Redirect to language-specific URL
 * Example: redirectToLanguage('fr') -> /fr/
 */
function redirectToLanguage(lang) {
    if (!translations[lang]) {
        console.warn('Invalid language for redirect:', lang);
        return;
    }

    // Get current path without language prefix
    let currentPath = window.location.pathname;
    const pathMatch = currentPath.match(/^\/([a-z]{2,3})(\/.*)?$/);

    if (pathMatch) {
        // Already has language prefix, replace it
        currentPath = pathMatch[2] || '/';
    }

    // Ensure path starts with /
    if (!currentPath.startsWith('/')) {
        currentPath = '/' + currentPath;
    }

    // Build new URL with language prefix
    const newPath = `/${lang}${currentPath === '/' ? '' : currentPath}`;
    const newUrl = window.location.origin + newPath + window.location.search + window.location.hash;

    console.log('Redirecting to:', newUrl);
    window.location.href = newUrl;
}

/**
 * Enhanced setLang that updates URL when language changes
 */
function setLangWithRedirect(lang, isUser = false) {
    if (!translations[lang]) lang = 'en';

    // Save language preference
    localStorage.setItem('fg_lang', lang);
    if (isUser) {
        localStorage.setItem('fg_manual', 'true');
    }

    // Check if current URL already has the correct language
    const urlLang = getLanguageFromURL();

    if (urlLang !== lang && isUser) {
        // User manually changed language, redirect to new language URL
        redirectToLanguage(lang);
    } else {
        // Just apply the language without redirect
        setLang(lang, isUser);
    }
}

async function initI18n() {
    console.log('Initializing i18n...');

    // Priority 1: Check URL for language parameter
    const urlLang = getLanguageFromURL();
    if (urlLang) {
        console.log('Using language from URL:', urlLang);
        setLang(urlLang, false);
        localStorage.setItem('fg_lang', urlLang);
        return;
    }

    // Priority 2: Check localStorage for saved preference
    const savedLang = localStorage.getItem('fg_lang');
    if (savedLang && translations[savedLang]) {
        console.log('Using saved language preference:', savedLang);
        setLang(savedLang, false);
        return;
    }

    // Priority 3: Detect from browser language
    console.log('No saved language, detecting from browser...');
    const browserLang = navigator.language.split('-')[0].toLowerCase();
    const detectedLang = translations[browserLang] ? browserLang : 'en';
    console.log('Detected language:', detectedLang);

    setLang(detectedLang, false);
    localStorage.setItem('fg_lang', detectedLang);
}

document.addEventListener('DOMContentLoaded', initI18n);

